var blogPosts = [...coreBlogPosts, ...extendedBlogPosts];

// src/lib/mcp/tools/content.ts
var SITE2 = "https://www.ltol.com";
var listLocationsTool = defineTool2({
  name: "list_locations",
  title: "List service areas",
  description: "List the cities and regions LTOL serves.",
  inputSchema: {},
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: () => {
    const rows = locations.map((l) => ({ slug: l.slug, city: l.city, region: l.region, tier: l.tier ?? "primary" }));
    return {
      content: [{ type: "text", text: rows.map((r) => `${r.city}, ${r.region} (${r.tier})`).join("\n") }],
      structuredContent: { locations: rows }
    };
  }
});
var searchBlogPostsTool = defineTool2({
  name: "search_blog_posts",
  title: "Search blog posts",
  description: "Search LTOL blog posts by keyword and/or category; returns up to 20 matches.",
  inputSchema: {
    query: z2.string().optional().describe("Keyword to match in title or summary."),
    category: z2.string().optional().describe("Category name to filter by, e.g. Cybersecurity.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ query, category }) => {
    const q = query?.toLowerCase();
    const c = category?.toLowerCase();
    const rows = blogPosts.filter((p) => (!q || `${p.title} ${p.metaDescription}`.toLowerCase().includes(q)) && (!c || p.category.toLowerCase() === c)).slice(0, 20).map((p) => ({ slug: p.slug, title: p.title, category: p.category, date: p.date, summary: p.metaDescription, url: `${SITE2}/blog/${p.slug}` }));
    return {
      content: [{ type: "text", text: rows.length ? rows.map((r) => `${r.slug}: ${r.title} [${r.category}]`).join("\n") : "No matching posts." }],
      structuredContent: { posts: rows }
    };
  }
});
var getBlogPostTool = defineTool2({
  name: "get_blog_post",
  title: "Get blog post",
  description: "Get the full text of one LTOL blog post by slug.",
  inputSchema: { slug: z2.string().min(1).describe("Blog post slug from search_blog_posts.") },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ slug }) => {
    const p = blogPosts.find((x) => x.slug === slug);
    if (!p) throw new ToolError2(`Unknown blog post "${slug}".`);
    const body = [p.intro, ...p.sections.map((s) => `## ${s.heading}
${s.content}`)].join("\n\n");
    return {
      content: [{ type: "text", text: `# ${p.title}

${body}

${SITE2}/blog/${p.slug}` }],
      structuredContent: { post: { slug: p.slug, title: p.title, category: p.category, date: p.date, body, url: `${SITE2}/blog/${p.slug}` } }
    };
  }
});
var getContactInfoTool = defineTool2({
  name: "get_contact_info",
  title: "Get contact info",
  description: "Get LTOL's phone, email, address and business hours.",
  inputSchema: {},
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: () => {
    const info = {
      phone: "+1-530-582-2080",
      email: "support@ltol.com",
      address: "10266 Truckee Airport Road, Suite C, Truckee, CA 96161",
      hours: "Monday\u2013Friday, 8am\u20136pm Pacific",
      website: SITE2
    };
    return { content: [{ type: "text", text: Object.entries(info).map(([k, v]) => `${k}: ${v}`).join("\n") }], structuredContent: { contact: info } };
  }
});

// src/lib/mcp/index.ts
var mcp_default = defineMcp({
  name: "ltol-2026",
  title: "LTOL 2026",
  version: "0.1.0",
  instructions: "Public information about LTOL, a local IT, AI and marketing company in Truckee, Tahoe and Reno: services, service areas, blog articles and contact details.",
  tools: [listServicesTool, getServiceTool, listLocationsTool, searchBlogPostsTool, getBlogPostTool, getContactInfoTool]
});

